import 'package:flutter/foundation.dart';import 'package:hive/hive.dart';import '../../../core/mesh/mesh_message.dart';enum MediaType { image, video, file }class MediaSearchResult {  final String messageId;  final String conversationId;  final String fileName;  final String filePath;  final MediaType type;  final DateTime timestamp;  final int? fileSize;  MediaSearchResult({    required this.messageId,    required this.conversationId,    required this.fileName,    required this.filePath,    required this.type,    required this.timestamp,    this.fileSize,  });}class SearchableMessage {  final String id;  final String senderId;  final String recipientId;  final String plaintext;  final DateTime timestamp;  final MeshMessageType type;  final String conversationId;  SearchableMessage({    required this.id,    required this.senderId,    required this.recipientId,    required this.plaintext,    required this.timestamp,    required this.type,    required this.conversationId,  });}class SearchResult {  final SearchableMessage message;  final int score;  final String highlightedText;  SearchResult({    required this.message,    required this.score,    required this.highlightedText,  });}class SearchService {  static const String _indexBox = 'catus_search_index';  final Map<String, Set<String>> _index = {};  final Map<String, SearchableMessage> _messages = {};  final Map<String, Set<String>> _mediaIndex = {};  final Map<String, MediaSearchResult> _mediaCache = {};  Future<void> initialize(List<MeshMessage> existingMessages) async {    await Hive.openBox<String>(_indexBox);    for (final msg in existingMessages) {      if (msg.type == MeshMessageType.text ||          msg.type == MeshMessageType.audio) {        _indexMessage(msg);      }    }    debugPrint('[Search] Indexed ${_messages.length} messages');  }  void indexNewMessage(MeshMessage message) {    _indexMessage(message);  }  List<SearchResult> search(    String query, {    String? senderPublicKey,    DateTime? from,    DateTime? to,    MeshMessageType? type,  }) {    if (query.trim().isEmpty) return [];    final tokens = _tokenize(query);    if (tokens.isEmpty) return [];    Set<String>? candidates;    for (final token in tokens) {      final matches = _index[token] ?? const {};      candidates = candidates == null          ? matches.toSet()          : (candidates.intersection(matches));    }    if (candidates == null || candidates.isEmpty) return [];    final results = <SearchResult>[];    for (final msgId in candidates) {      final msg = _messages[msgId];      if (msg == null) continue;      if (senderPublicKey != null && msg.senderId != senderPublicKey) continue;      if (from != null && msg.timestamp.isBefore(from)) continue;      if (to != null && msg.timestamp.isAfter(to)) continue;      if (type != null && msg.type != type) continue;      final msgTokens = _tokenize(msg.plaintext);      int score = 0;      for (final t in tokens) {        score += msgTokens.where((mt) => mt == t).length;      }      results.add(SearchResult(        message: msg,        score: score,        highlightedText: _highlight(msg.plaintext, tokens),      ));    }    results.sort((a, b) => b.score.compareTo(a.score));    return results;  }  void _indexMessage(MeshMessage msg) {    final plaintext = msg.content;    final searchable = SearchableMessage(      id: msg.id,      senderId: msg.senderId,      recipientId: msg.recipientId,      plaintext: plaintext,      timestamp: msg.timestamp,      type: msg.type,      conversationId: _convId(msg.senderId, msg.recipientId),    );    _messages[msg.id] = searchable;    for (final token in _tokenize(plaintext)) {      _index.putIfAbsent(token, () => {}).add(msg.id);    }  }  List<String> _tokenize(String text) {    return text        .toLowerCase()        .replaceAll(RegExp(r'[^\w\s]'), ' ')        .split(RegExp(r'\s+'))        .where((t) => t.length >= 2)        .toList();  }  String _highlight(String text, List<String> tokens) {    var result = text;    for (final token in tokens) {      result = result.replaceAllMapped(        RegExp('($token)', caseSensitive: false),        (m) => '**${m.group(1)}**',      );    }    return result;  }  String _convId(String id1, String id2) {    final sorted = [id1, id2]..sort();    return sorted.join('_');  }  void removeFromIndex(String messageId) {    _messages.remove(messageId);    for (final ids in _index.values) {      ids.remove(messageId);    }  }  void clear() {    _index.clear();    _messages.clear();    _mediaIndex.clear();    _mediaCache.clear();  }  void indexMediaAttachment({    required String messageId,    required String conversationId,    required String fileName,    required String filePath,    required MediaType type,    required DateTime timestamp,    int? fileSize,  }) {    final media = MediaSearchResult(      messageId: messageId,      conversationId: conversationId,      fileName: fileName,      filePath: filePath,      type: type,      timestamp: timestamp,      fileSize: fileSize,    );    _mediaCache[messageId] = media;    for (final token in _tokenize(fileName)) {      _mediaIndex.putIfAbsent(token, () => {}).add(messageId);    }    _mediaIndex.putIfAbsent(type.name, () => {}).add(messageId);  }  List<MediaSearchResult> searchMedia({    MediaType? type,    String? conversationId,    DateTime? from,    DateTime? to,  }) {    final Set<String> candidates;    if (type != null) {      candidates = _mediaIndex[type.name]?.toSet() ?? {};    } else {      candidates = _mediaIndex.values.expand((s) => s).toSet();    }    if (candidates.isEmpty) return [];    final results = <MediaSearchResult>[];    for (final msgId in candidates) {      final media = _mediaCache[msgId];      if (media == null) continue;      if (conversationId != null && media.conversationId != conversationId)        continue;      if (from != null && media.timestamp.isBefore(from)) continue;      if (to != null && media.timestamp.isAfter(to)) continue;      results.add(media);    }    results.sort((a, b) => b.timestamp.compareTo(a.timestamp));    return results;  }  List<MediaSearchResult> searchMediaByQuery(String query, {MediaType? type}) {    if (query.trim().isEmpty) {      return searchMedia(type: type);    }    final tokens = _tokenize(query);    if (tokens.isEmpty) return [];    Set<String>? candidates;    for (final token in tokens) {      final matches = _mediaIndex[token] ?? const {};      candidates = candidates == null          ? matches.toSet()          : (candidates.intersection(matches));    }    if (candidates == null || candidates.isEmpty) return [];    final results = <MediaSearchResult>[];    for (final msgId in candidates) {      final media = _mediaCache[msgId];      if (media == null) continue;      if (type != null && media.type != type) continue;      results.add(media);    }    return results;  }  Map<MediaType, List<MediaSearchResult>> getMediaGroupedByType({    String? conversationId,    int limit = 50,  }) {    final allMedia = searchMedia(conversationId: conversationId);    final grouped = <MediaType, List<MediaSearchResult>>{      MediaType.image: [],      MediaType.video: [],      MediaType.file: [],    };    for (final media in allMedia.take(limit)) {      grouped[media.type]?.add(media);    }    return grouped;  }  void removeMediaFromIndex(String messageId) {    _mediaCache.remove(messageId);    for (final ids in _mediaIndex.values) {      ids.remove(messageId);    }  }}